if (!/<title>[\s\S]*?<\/title>/i.test(code)) {
  throw new Error("No <title> element found — it belongs inside the <head>.");
}

const m = code.match(/<title>([\s\S]*?)<\/title>/i);
if (!m || m[1].trim() !== "About Me") {
  throw new Error("The title text must be exactly: About Me");
}

if (!/<head[\s\S]*<title>[\s\S]*<\/title>[\s\S]*<\/head>/i.test(code)) {
  throw new Error("The <title> must be inside the <head>, not the body.");
}

if (!/<p>All about me and what I am learning\.<\/p>/.test(code)) {
  throw new Error("The original body paragraph should stay exactly as it was.");
}
